package com.narad.search.lib.query.model

import com.narad.search.lib.query.TestModel
import org.json.JSONObject
import org.junit.After
import org.junit.Assert.*
import org.junit.Before
import org.junit.Test
import kotlin.math.sqrt

/**
 * JVM parity test: Kotlin DJL tokenizer token IDs match Python HF tokenizers IDs,
 * and Kotlin 256-dim EG2 embeddings match the Python reference with cosine >= 0.999.
 *
 * The reference fixture was generated by `tools/eg2-trial/generate_fixture.py`
 * using onnxruntime 1.30.0 + tokenizers 0.23.2 on the same tuned ONNX graph.
 *
 * Fixture resource: `lib/src/test/resources/embeddinggemma2_parity_fixture.json`.
 *
 * Four fixed strings are tested (see the fixture JSON for exact values):
 *   en_query - English search query (with QUERY_PREFIX applied)
 *   hi_query - Hindi search query (with QUERY_PREFIX applied)
 *   en_doc   - English document chunk (with DOC_PREFIX applied)
 *   hi_doc   - Hindi document chunk (with DOC_PREFIX applied)
 *
 * DoD #2: cosine(kotlin_emb, python_emb) >= 0.999 for all four strings.
 */
class EmbeddingParityTest {

    private lateinit var tokenizer: HuggingFaceTokenizer
    private lateinit var model: EmbeddingModel
    private lateinit var fixture: JSONObject

    @Before
    fun setUp() {
        TestModel.skipIfMissing()
        tokenizer = HuggingFaceTokenizer(TestModel.tokenizerJsonPath)
        model = EmbeddingModel(TestModel.onnxPath, tokenizer)
        val fixtureText = EmbeddingParityTest::class.java.classLoader!!
            .getResourceAsStream("embeddinggemma2_parity_fixture.json")!!
            .bufferedReader()
            .readText()
        fixture = JSONObject(fixtureText)
    }

    @After
    fun tearDown() {
        if (::model.isInitialized) model.close()
    }

    @Test
    fun `en_query token IDs match Python reference`() = checkTokenIds("en_query")

    @Test
    fun `hi_query token IDs match Python reference`() = checkTokenIds("hi_query")

    @Test
    fun `en_doc token IDs match Python reference`() = checkTokenIds("en_doc")

    @Test
    fun `hi_doc token IDs match Python reference`() = checkTokenIds("hi_doc")

    @Test
    fun en_query_embedding_cosine_matches_python_reference() = checkEmbedding("en_query")

    @Test
    fun hi_query_embedding_cosine_matches_python_reference() = checkEmbedding("hi_query")

    @Test
    fun en_doc_embedding_cosine_matches_python_reference() = checkEmbedding("en_doc")

    @Test
    fun hi_doc_embedding_cosine_matches_python_reference() = checkEmbedding("hi_doc")

    // -------------------------------------------------------------------------
    // Private helpers
    // -------------------------------------------------------------------------

    private fun checkTokenIds(key: String) {
        val entry = fixture.getJSONObject(key)
        val prompted = entry.getString("prompted")
        val expectedIds = entry.getJSONArray("token_ids")

        val enc = tokenizer.encode(prompted)

        assertEquals(
            "$key: token count mismatch (prompted='$prompted')",
            expectedIds.length(),
            enc.inputIds.size
        )
        for (i in 0 until expectedIds.length()) {
            assertEquals(
                "$key: token[$i] mismatch",
                expectedIds.getLong(i),
                enc.inputIds[i]
            )
        }
    }

    private fun checkEmbedding(key: String) {
        val entry = fixture.getJSONObject(key)
        val rawText = entry.getString("raw")
        val kind = if (key.endsWith("_query")) "query" else "doc"

        val kotlinEmb: FloatArray = if (kind == "query") {
            model.embedQuery(rawText)
        } else {
            model.embedDocument(rawText)
        }

        val pyArr = entry.getJSONArray("embedding_256")
        val pyEmb = FloatArray(pyArr.length()) { pyArr.getDouble(it).toFloat() }

        val cos = dot(kotlinEmb, pyEmb)
        println("cosine($key kotlin vs python) = $cos")
        assertTrue(
            "$key: cosine(kotlin, python) = $cos must be >= 0.999",
            cos >= 0.999f
        )
    }

    private fun dot(a: FloatArray, b: FloatArray): Float {
        // Both are L2-normalised so dot = cosine.
        var sum = 0.0
        for (i in a.indices) sum += a[i].toDouble() * b[i].toDouble()
        return sum.toFloat()
    }
}
